/**
 * Append-only event ledger. Balances are derived by folding the event stream.
 */
export function createLedger() {
  const events = []
  let transfersStarted = false

  function validateAmount(amountCents) {
    if (!Number.isSafeInteger(amountCents) || amountCents <= 0) {
      throw new Error('amount must be positive')
    }
  }

  function balanceOf(account) {
    let balance = 0
    for (const event of events) {
      if (event.account === account) {
        balance += event.type === 'credit' ? event.amountCents : -event.amountCents
      }
    }
    return balance
  }

  function store(event) {
    events.push({ seq: events.length, ...event })
  }

  return {
    append(event) {
      if (transfersStarted || event.type !== 'credit') {
        throw new Error('only initial funding credits may be appended directly')
      }
      validateAmount(event.amountCents)

      if (!Number.isSafeInteger(balanceOf(event.account) + event.amountCents)) {
        throw new Error('balance exceeds safe integer range')
      }
      store(event)
    },
    appendTransfer(debit, credit) {
      validateAmount(debit.amountCents)
      validateAmount(credit.amountCents)
      if (debit.type !== 'debit' || credit.type !== 'credit' || debit.amountCents !== credit.amountCents) {
        throw new Error('invalid transfer events')
      }

      const senderBalance = balanceOf(debit.account)
      if (senderBalance < debit.amountCents) throw new Error('insufficient funds')

      if (debit.account !== credit.account) {
        const recipientBalance = balanceOf(credit.account)
        if (!Number.isSafeInteger(recipientBalance + credit.amountCents)) {
          throw new Error('balance exceeds safe integer range')
        }
      }

      transfersStarted = true
      store(debit)
      store(credit)
    },
    eventCount() {
      return events.length
    },
    fold() {
      const balances = new Map()
      for (const event of events) {
        const current = balances.get(event.account) ?? 0
        balances.set(event.account, current + (event.type === 'credit' ? event.amountCents : -event.amountCents))
      }
      return Object.fromEntries(balances)
    },
    events() {
      return events.map((event) => ({ ...event }))
    },
  }
}

